// FILE: frontend/src/LogDetail.js
//
// --- VERSION 1.8.0 ---
// - Integrated a new `TripMap` component to display the GPS path of the trip.
// - Implemented robust client-side zooming and panning using `chartjs-plugin-zoom`.
// - Replaced the cluttered annotation labels with a dynamic tooltip that shows
//   the operating state and normal range for the data point under the cursor.
// -----------------------------

import React, { useState, useEffect, useMemo } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import annotationPlugin from 'chartjs-plugin-annotation';
import zoomPlugin from 'chartjs-plugin-zoom'; // New
import TripMap from './TripMap'; // New

ChartJS.register( CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, annotationPlugin, zoomPlugin );

const CHART_COLORS = [ '#38BDF8', '#F59E0B', '#4ADE80', '#F472B6', '#A78BFA', '#2DD4BF', '#FB7185', '#FACC15' ];
const ANOMALY_COLOR = '#EF4444'; // red-500

function LogDetail() {
  const { logId } = useParams();
  const [logData, setLogData] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [availablePIDs, setAvailablePIDs] = useState([]);
  const [selectedPIDs, setSelectedPIDs] = useState(new Set(['vehicle_speed', 'engine_rpm']));
  const [status, setStatus] = useState('Loading log data...');
  const [logFileName, setLogFileName] = useState('');


const [gpsData, setGpsData] = useState([]);
  useEffect(() => {
	const fetchLogData = async () => {
	  try {
		const logInfoResponse = await axios.get('http://localhost:5001/api/logs');
		const currentLog = logInfoResponse.data.find(log => log.log_id === parseInt(logId));
		if (currentLog) setLogFileName(currentLog.file_name);

		const response = await axios.get(`http://localhost:5001/api/logs/${logId}/data`);
		const { data, columns, statistics } = response.data;

		if (data && data.length > 0) {
		  setLogData(data);
		  setStatistics(statistics);
		  setAvailablePIDs(columns.filter(c => !['data_id', 'timestamp', 'operating_state'].includes(c)));
		  const latCol = columns.find(c => c.includes('latitude'));
		  const lonCol = columns.find(c => c.includes('longitude'));
		  if (latCol && lonCol) {
			setGpsData(data.map(row => [row[latCol], row[lonCol]]).filter(p => p[0] && p[1]));
		    }
		} else {
		  setStatus('No data rows found for this log.');
		}
	  } catch (error) {
		console.error("Error fetching log detail:", error);
		setStatus('Failed to load log data.');
	  }
	};
	fetchLogData();
  }, [logId]);

  const handlePIDSelectionChange = (pid) => {
	setSelectedPIDs(prev => {
	  const newSelected = new Set(prev);
	  if (newSelected.has(pid)) newSelected.delete(pid);
	  else newSelected.add(pid);
	  return newSelected;
	});
  };

  const chartData = useMemo(() => {
	if (!logData || logData.length === 0) return null;

	const labels = logData.map(row => new Date(row.timestamp * 1000).toLocaleTimeString());

	return {
	  labels,
	  datasets: Array.from(selectedPIDs).map((pid, index) => {
		const pidStats = statistics[pid] || {};

		const pointColors = logData.map(row => {
			const state = row.operating_state;
			const stateStats = pidStats[state];
			if (stateStats && stateStats.std_dev > 0) {
				const value = row[pid];
				const deviation = Math.abs(value - stateStats.mean) / stateStats.std_dev;
				return deviation > 2.5 ? ANOMALY_COLOR : CHART_COLORS[index % CHART_COLORS.length];
			}
			return CHART_COLORS[index % CHART_COLORS.length];
		});

		const pointRadii = pointColors.map(color => color === ANOMALY_COLOR ? 5 : 1);

		return {
		  label: pid.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
		  data: logData.map(row => row[pid]),
		  borderColor: CHART_COLORS[index % CHART_COLORS.length],
		  yAxisID: `y${index}`,
		  tension: 0.4,
		  borderWidth: 2,
		  pointBackgroundColor: pointColors,
		  pointBorderColor: pointColors,
		  pointRadius: pointRadii,
		  pointHoverRadius: 7,
		};
	  }),
	};
  }, [logData, selectedPIDs, statistics]);

  const chartOptions = useMemo(() => {
	const scales = { x: { ticks: { color: '#9CA3AF' } } };
	const annotations = {};
	const selectedArray = Array.from(selectedPIDs);

	selectedArray.forEach((pid, index) => {
		scales[`y${index}`] = {
			type: 'linear',
			display: true,
			position: index % 2 === 0 ? 'left' : 'right',
			title: { display: true, text: pid.replace(/_/g, ' '), color: CHART_COLORS[index % CHART_COLORS.length] },
			ticks: { color: CHART_COLORS[index % CHART_COLORS.length] },
			grid: { drawOnChartArea: index === 0 },
		};
	});

	if (selectedArray.length > 0) {
		const primaryPID = selectedArray[0];
		const pidStats = statistics[primaryPID];
		if (pidStats) {
			Object.entries(pidStats).forEach(([state, stats]) => {
				if (stats && stats.std_dev > 0) {
					annotations[`box_${state}`] = {
						type: 'box',
						yMin: stats.mean - stats.std_dev,
						yMax: stats.mean + stats.std_dev,
						backgroundColor: 'rgba(100, 116, 139, 0.2)',
						borderColor: 'rgba(100, 116, 139, 0.4)',
						borderWidth: 1,
						label: {
							content: `${state} Normal Range`,
							display: true,
							position: 'start',
							color: 'rgba(156, 163, 175, 0.7)',
							font: { size: 10 }
						},
						yScaleID: 'y0' 
					};
				}
			});
		}
	}

	return {
			responsive: true,
			maintainAspectRatio: false,
			interaction: { mode: 'index', intersect: false },
			plugins: {
				title: { display: true, text: `Trip Data for: ${logFileName}`, color: '#FFFFFF', font: { size: 18 } },
				legend: { display: false },
				annotation: { annotations: annotations },
				tooltip: {
					callbacks: {
						footer: function(tooltipItems) {
							const item = tooltipItems[0];
							const row = logData[item.dataIndex];
							const state = row.operating_state;
							const pid = item.dataset.yAxisID.startsWith('y') ? selectedArray[parseInt(item.dataset.yAxisID.substring(1))] : null;
							if (state && pid && statistics[pid] && statistics[pid][state]) {
								const stats = statistics[pid][state];
								const mean = stats.mean.toFixed(2);
								const std = stats.std_dev.toFixed(2);
								return `State: ${state}\nNormal Range: ${mean} ± ${std}`;
							}
							return `State: ${state || 'N/A'}`;
						}
					}
				},
				zoom: { // New zoom configuration
					pan: { enabled: true, mode: 'x' },
					zoom: { wheel: { enabled: true }, pinch: { enabled: true }, mode: 'x' },
				}
			},
			scales: scales,
		};
	  }, [selectedPIDs, logFileName, statistics, logData]);

  return (
	<div className="space-y-6">
		<div className="grid grid-cols-1 md:grid-cols-4 gap-6">
			<div className="md:col-span-3 bg-gray-800 rounded-lg shadow-xl p-4 h-[70vh]">
			{chartData ? ( <Line options={chartOptions} data={chartData} /> ) : ( <p className="flex items-center justify-center h-full text-gray-400">{status}</p> )}
			</div>
			<div className="md:col-span-1 bg-gray-800 rounded-lg shadow-xl p-4">
				<h3 className="text-lg font-bold border-b-2 border-cyan-500 pb-2 mb-3">Select PIDs to Display</h3>
				<div className="flex flex-col space-y-2 max-h-[65vh] overflow-y-auto">
					{availablePIDs.map(pid => (<label key={pid} className="flex items-center space-x-3 cursor-pointer p-2 rounded-md hover:bg-gray-700"><input type="checkbox" className="h-4 w-4 rounded bg-gray-600 border-gray-500 text-cyan-500 focus:ring-cyan-600" checked={selectedPIDs.has(pid)} onChange={() => handlePIDSelectionChange(pid)} /><span className="text-sm capitalize">{pid.replace(/_/g, ' ')}</span></label>))}
				</div>
			</div>
			{gpsData.length > 0 && (<div className="bg-gray-800 rounded-lg shadow-xl p-4 h-[50vh]"><TripMap positions={gpsData} /></div>)}
		</div>
	</div>
  );
}
export default LogDetail;
